paraphrases:[P('understand money matters','be financially literate','understand personal finance','possess practical financial knowledge','financially literate涵盖预算、信贷和风险。'),P('borrow money','take out credit','obtain a loan','use funds supplied by a lender','credit既可指信贷也可指赊购额度。'),P('repay a debt','pay off a debt','settle an outstanding balance','meet a financial obligation to a lender','settle强调结清。'),P('compare products','shop around','evaluate competing offers','assess alternatives across providers','shop around自然且适合Speaking。'),P('hidden cost','an unexpected charge','a less visible fee','a cost disclosed only in detailed conditions','less visible比hidden更谨慎。'),P('plan for retirement','prepare financially for later life','build retirement provision','make long-term pension arrangements','provision表示为未来准备的资金保障。'),P('financial risk','the possibility of financial loss','exposure to monetary loss','uncertainty affecting future returns','exposure常与risk搭配。'),P('money advice','financial guidance','personal-finance education','professional advice on financial decisions','professional advice不等同于一般教育。')],
